/* ---------------- SHARED IMAGE SOURCES (embedded once, reused everywhere) ---------------- */
/* Previously this same base64 image data was duplicated inline 3x each (doctor photo,
   clinic logo), bloating the file by ~500KB and slowing the very first paint — which is
   exactly the window the OS-level PWA splash screen is filling. Embedding each once here
   and assigning it to every <img data-img-src> via JS cuts that dead weight. */
const DOCTOR_IMG_SRC = "data:image/jpeg;base64,";
const LOGO_IMG_SRC = "data:image/png;base64,";
const SPLASH_BG_SRC = "data:image/jpeg;base64,";

document.querySelectorAll('img[data-img-src="doctor"]').forEach(img => img.src = DOCTOR_IMG_SRC);
document.querySelectorAll('img[data-img-src="logo"]').forEach(img => img.src = LOGO_IMG_SRC);
document.querySelectorAll('img[data-img-src="splashbg"]').forEach(img => img.src = SPLASH_BG_SRC);

